def family(name):
 n=name.lower()
 for key,words in [('sensitivity',['data-table']),('rules',['conditional','validation']),('names',['names.','defined-name']),('pivots',['pivot','slicer']),('comments',['thread','comment','note']),('charts',['chart','axis']),('drawings',['image','shape','sparkline','drawing']),('formatting',['format','style','theme','freeze','gridlines']),('tables',['table']),('ranges',['range','getcell','columnindex','rowindex']),('formulas',['formula','recalculate']),('inspection',['inspect','help','resolve']),('files',['export','render','csv','markdown','html']),('changes',['awareness','record','crdt','session']),('workbooks',['workbook','worksheet','sheet','utils'])]:
  if any(w in n for w in words):return key
 return 'workbooks'
