ops=[]
for r in read('ops.json'):
 if r['id']=='OP-invalid':continue
 d=r['detail'];op=d['input']['op'];record={**d,'id':r['id'],'title':op,'family':family(op),'summary':r['description'],'kind':'operation','code':'workbook.apply('+json.dumps([d['input']],ensure_ascii=False,indent=2)+');','status':'Executed','source':'../2026-09-15-artifact-tool-reference/files/runs/ops.json'}
 target=d['input'].get('target');sheet=target.get('sheet') if isinstance(target,dict) else d['input'].get('sheet')
 raw=read('op-'+r['id'][3:]+'.json')
 sh=next((x for x in raw['after']['sheets'] if x['name']==sheet),None)
 if sh:record['cells']=[{k:c.get(k) for k in ['address','value','formula','dataType'] if k in c} for row in sh.get('rows',[])[:6] for c in row.get('cells',[])[:6]]
 ops.append(record)
apis=[]
apiExamples=[(h,e) for h in help if h.get('kind')=='api' for e in h.get('examples',[])]
for r in read('api-example-results.json'):
 h,e=apiExamples[r['index']]
 assert h['name']==r['name']
 capturedInput={**e,'adaptations':r.get('adaptations',[])}
 apis.append(dict(id='api-'+str(r['index']),title=r.get('summary') or r['name'],family=family(r['name']),name=r['name'],summary=h.get('summary',r['name']),kind='api',input=capturedInput,result={k:r[k] for k in ['execution','export','exportError','logs'] if k in r},code=r.get('originalCode') or json.dumps(e,ensure_ascii=False,indent=2),notes=h.get('notes',[]),status='Export fails' if r.get('exportError') else 'Executed',source='../2026-09-15-artifact-tool-reference/files/runs/api-example-'+str(r['index']).zfill(3)+'.json'))
