 formulas.append(dict(id=x['name'],title=x['name'][3:],category=x['category'],summary=h['summary'],notes=h.get('notes',[]),input={'formula':e['formula'],'fixture':'Sheet1 and Data A1:E20: row i = [i,2i,3i,4i,5i], i=1…20'},result=e,status=status,oracle=oracles.get(x['name'][3:]),kind='formula',code=e['formula']))
