 dict(id='labels',title='A valid-looking assignment can break export',family='charts',expected='Chart labels display and the workbook exports.',observed='The assignment completes; export throws toProto is not a function.',why='Replacing a nested facade with a plain object removes its serialization methods.',repair='Set chart.dataLabels.showValue = true on the existing object.',input=read('api-example-020.json')['originalCode'],result=read('api-example-020.json')['exportError'],code='chart.dataLabels = {showValue:true};'),
 dict(id='validation',title='An input rule is not a JavaScript guard',family='rules',expected='A whole-number rule from 1 to 10 rejects 999.',observed='The programmatic write of 999 is accepted.',why='The rule describes spreadsheet input validation; the mutation path does not enforce it.',repair='Validate incoming values in the wrapper before writing.',input={'min':1,'max':10,'write':999},result=probes['F02']['detail'],code='range.values = [[999]];'),
